changes.before:
/* stylelint-disable no-duplicate-selectors -- legacy sheet: rules were appended over time; merging them would reorder the cascade (2026-09-07) */

/* stylelint-disable declaration-no-important -- legacy sheet: a stack of overrides and Caspio/inline-style fights; the flags come out together when the page is untangled (2026-09-07) */

/* Page theme (CSS standardization, 2026-09-07): this page's own colours, auto-named by hue, merged into its
   existing :root. Map them to shared_components/css/tokens.css names when the page is redesigned;
   raw hex is allowed ONLY in this block. */
/* stylelint-disable color-no-hex */
  :root {
    --garment-designer-red: #b3392b;
    --garment-designer-yellow-dark: #6c5200;
    --garment-designer-gray: #bbb;
    --garment-designer-yellow: #e1b844;
    --garment-designer-yellow-dark-2: #5d4700;
    --garment-designer-blue: #4f46e5;
    --garment-designer-indigo-2: #6d28d9;
    --garment-designer-green-dark: #236414;
    --garment-designer-yellow-2: #d4a017;
    --garment-designer-gray-2: #6b7a63;
    --garment-designer-gray-3: #666;
    --garment-designer-red-2: #c8102e;
    --garment-designer-green: #b8cdb0;
    --garment-designer-green-2: #cdd8c7;
    --garment-designer-cyan-tint: #cbdced;
    --garment-designer-green-3: #bcc8b7;
    --garment-designer-cyan: #214d7c;
    --garment-designer-green-4: #3d7a26;
    --garment-designer-red-3: #e3b5af;
    --garment-designer-red-4: #d9534f;

    /* ---- NWCA brand colors — adjust to match your site ---- */
    --brand:        var(--brand-700);
    --brand-dark:   var(--store-green-900);
    --brand-darker: var(--store-green-950);
    --brand-light:  var(--brand-100);
    --brand-mid:    var(--brand-600);
    --accent:       var(--garment-designer-yellow-2);

    /* ------------------------------------------------------- */
    --bg:        var(--gray-100);
    --panel:     var(--color-surface);
    --border:    var(--store-line);
    --text:      #22301c; /* the designer's own ink, kept exact: the storefront ink (#182219) is a shade darker on every heading */
    --text-dim:  var(--garment-designer-gray-2);
    --checker-a: var(--gray-200);
    --checker-b: var(--store-paper);
  }
/* stylelint-enable color-no-hex */
  * { box-sizing: border-box; margin: 0; padding: 0; }
  html, body { height: 100%; }

  body {
    font-family: 'Segoe UI', system-ui, -apple-system, Arial, sans-serif;
    background: var(--bg);
    color: var(--text);
    display: flex;
    flex-direction: column;
    overflow: hidden;
  }

  /* ---------- Header ---------- */
  header {
    background: linear-gradient(135deg, var(--brand-dark), var(--brand));
    color: var(--color-on-brand);
    padding: 10px 18px;
    display: flex;
    align-items: center;
    gap: 12px;
    flex-shrink: 0;
  }

  .logo-badge {
    width: 36px; height: 36px;
    border-radius: 8px;
    background: var(--color-surface);
    color: var(--brand);
    font-weight: 800;
    font-size: 13px;
    display: flex; align-items: center; justify-content: center;
    letter-spacing: .5px;
    flex-shrink: 0;
  }
  header .titles { line-height: 1.2; min-width: 0; }
  header h1 { font-size: 16px; font-weight: 700; white-space: nowrap; }
  header .sub { font-size: 12px; opacity: .85; white-space: nowrap; }
  header .spacer { flex: 1; }

  .privacy-note {
    font-size: 11px;
    opacity: .85;
    text-align: right;
    line-height: 1.3;
  }
  .privacy-note b { color: var(--color-on-brand); }

  .header-lib-link {
    color: var(--color-on-brand);
    background: rgb(255 255 255 / 14%);
    border: 1px solid rgb(255 255 255 / 40%);
    border-radius: 9px;
    padding: 8px 12px;
    font-size: 13px;
    font-weight: 800;
    text-decoration: none;
    white-space: nowrap;
    margin-right: 14px;
  }
  .header-lib-link:hover { background: rgb(255 255 255 / 26%); }

  /* ---------- Layout ---------- */
  main { flex: 1; display: flex; min-height: 0; }

  /* File list sidebar */
  #sidebar {
    width: 200px;
    background: var(--panel);
    border-right: 1px solid var(--border);
    display: none;
    flex-direction: column;
    flex-shrink: 0;
  }
  #sidebar.visible { display: flex; }

  #sidebar .side-head {
    padding: 10px 12px;
    font-size: 11px;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: .6px;
    color: var(--text-dim);
    border-bottom: 1px solid var(--border);
    display: flex; align-items: center; justify-content: space-between;
  }
  #fileList { flex: 1; overflow-y: auto; padding: 6px; }

  .file-item {
    display: flex; align-items: center; gap: 8px;
    padding: 7px 8px;
    border-radius: 8px;
    cursor: pointer;
    border: 1px solid transparent;
    margin-bottom: 4px;
  }
  .file-item:hover { background: var(--brand-light); }
  .file-item.active { background: var(--brand-light); border-color: var(--brand-mid); }

  .file-item .thumb {
    width: 40px; height: 40px;
    border-radius: 6px;
    background:
      linear-gradient(45deg, var(--checker-a) 25%, transparent 25%, transparent 75%, var(--checker-a) 75%),
      linear-gradient(45deg, var(--checker-a) 25%, var(--checker-b) 25%, var(--checker-b) 75%, var(--checker-a) 75%);
    background-size: 12px 12px;
    background-position: 0 0, 6px 6px;
    border: 1px solid var(--border);
    display: flex; align-items: center; justify-content: center;
    overflow: hidden;
    flex-shrink: 0;
    font-size: 9px; font-weight: 700; color: var(--text-dim);
  }
  .file-item .thumb canvas, .file-item .thumb img { max-width: 100%; max-height: 100%; }
  .file-item .meta { min-width: 0; flex: 1; }
  .file-item .fname { font-size: 12px; font-weight: 600; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  .file-item .fsize { font-size: 10px; color: var(--text-dim); }

  .file-item .badge {
    font-size: 9px; font-weight: 800;
    padding: 2px 5px; border-radius: 4px;
    background: var(--brand); color: var(--color-on-brand);
    flex-shrink: 0;
  }
  .file-item .badge.err { background: var(--garment-designer-red); }
  .file-item .badge.load { background: var(--text-dim); }

  /* Viewer column */
  #viewerCol { flex: 1; display: flex; flex-direction: column; min-width: 0; }

  /* Toolbar */
  #toolbar {
    background: var(--panel);
    border-bottom: 1px solid var(--border);
    padding: 7px 12px;
    display: none;
    align-items: center;
    gap: 6px;
    flex-wrap: wrap;
    flex-shrink: 0;
  }
  #toolbar.visible { display: flex; }

  .tbtn {
    border: 1px solid var(--border);
    background: var(--color-surface);
    color: var(--text);
    border-radius: 7px;
    padding: 6px 11px;
    font-size: 13px;
    font-weight: 600;
    cursor: pointer;
    display: inline-flex; align-items: center; gap: 6px;
    white-space: nowrap;
  }
  .tbtn:hover { background: var(--brand-light); border-color: var(--brand-mid); }
  .tbtn:disabled { opacity: .4; cursor: default; }
  .tbtn:disabled:hover { background: var(--color-surface); border-color: var(--border); }
  .tbtn.primary { background: var(--brand); border-color: var(--brand); color: var(--color-on-brand); }
  .tbtn.primary:hover { background: var(--brand-dark); }
  .tgroup { display: inline-flex; gap: 0; }
  .tgroup .tbtn { border-radius: 0; margin-left: -1px; }
  .tgroup .tbtn:first-child { border-radius: 7px 0 0 7px; margin-left: 0; }
  .tgroup .tbtn:last-child { border-radius: 0 7px 7px 0; }
  #zoomLabel { font-size: 12px; color: var(--text-dim); min-width: 46px; text-align: center; font-weight: 700; }
  #pageNav { display: none; align-items: center; gap: 6px; }
  #pageNav.visible { display: inline-flex; }
  #pageLabel { font-size: 12px; color: var(--text-dim); font-weight: 700; white-space: nowrap; }
  .tb-spacer { flex: 1; }
  .tsep { width: 1px; height: 22px; background: var(--border); margin: 0 4px; }

  /* Stage (canvas area) */
  #stageWrap { flex: 1; position: relative; min-height: 0; display: flex; }

  #stage {
    flex: 1;
    position: relative;
    overflow: hidden;
    background:
      linear-gradient(45deg, var(--checker-a) 25%, transparent 25%, transparent 75%, var(--checker-a) 75%),
      linear-gradient(45deg, var(--checker-a) 25%, var(--checker-b) 25%, var(--checker-b) 75%, var(--checker-a) 75%);
    background-size: 24px 24px;
    background-position: 0 0, 12px 12px;
    cursor: grab;
    touch-action: none;
  }
  #stage.panning { cursor: grabbing; }

  #canvasHolder {
    position: absolute;
    top: 0; left: 0;
    transform-origin: 0 0;
    box-shadow: 0 4px 24px rgb(20 40 10 / 18%);
    line-height: 0;

    /* transparent so artwork transparency shows the garment color / checkerboard behind it */
    background: transparent;
  }
  #stage.eyedrop { cursor: crosshair; }

  /* Garment background swatches */
  .bgswatches { display: inline-flex; align-items: center; gap: 5px; }
  .bgswatches .lbl { font-size: 11px; font-weight: 700; color: var(--text-dim); margin-right: 2px; }

  .bgsw {
    width: 22px; height: 22px;
    border-radius: 50%;
    border: 2px solid var(--border);
    cursor: pointer;
    padding: 0;
    flex-shrink: 0;
  }
  .bgsw.active { border-color: var(--brand); box-shadow: 0 0 0 2px var(--brand-light); }

  .bgsw.checker {
    background: linear-gradient(45deg, var(--gray-300) 25%, transparent 25%, transparent 75%, var(--gray-300) 75%), linear-gradient(45deg, var(--gray-300) 25%, var(--color-surface) 25%, var(--color-surface) 75%, var(--gray-300) 75%);
    background-size: 8px 8px;
    background-position: 0 0, 4px 4px;
  }
  #bgCustom { width: 26px; height: 26px; border: 2px solid var(--border); border-radius: 50%; padding: 0; cursor: pointer; background: none; }
  #bgCustom.active { border-color: var(--brand); }

  /* Eyedropper sample chip */
  #eyeChip {
    display: none;
    align-items: center; gap: 5px;
    font-size: 11px; font-weight: 700;
    padding: 3px 8px 3px 3px;
    border: 1px solid var(--border);
    border-radius: 14px;
    cursor: pointer;
    background: var(--color-surface);
  }
  #eyeChip .dot { width: 16px; height: 16px; border-radius: 50%; border: 1px solid var(--border); }
  #eyeChip.visible { display: inline-flex; }

  /* Ink colors / screens list in info panel */
  .ink-row {
    display: flex; align-items: center; gap: 8px;
    padding: 4px 5px;
    margin-bottom: 3px;
    border-radius: 7px;
    border: 1px solid transparent;
    cursor: pointer;
  }
  .ink-row:hover { background: var(--brand-light); }
  .ink-row.active { border-color: var(--brand); background: var(--brand-light); }

  .ink-row .sw {
    width: 26px; height: 26px;
    border-radius: 6px;
    border: 1px solid var(--border);
    flex-shrink: 0;
  }
  .ink-meta { font-size: 11px; font-weight: 600; line-height: 1.35; min-width: 0; }
  .ink-hex { cursor: copy; }
  .ink-hex:hover { text-decoration: underline; }
  .ink-pms { color: var(--text-dim); font-weight: 600; }
  .pal-hint { font-size: 10px; color: var(--text-dim); margin-top: 5px; line-height: 1.45; }

  .sep-exit {
    margin-top: 6px;
    width: 100%;
    text-align: center;
    justify-content: center;
  }

  /* Print-readiness check */
  .pc-line { display: flex; gap: 6px; font-size: 12px; line-height: 1.45; margin-bottom: 7px; font-weight: 600; }
  .pc-ok { color: var(--brand); }
  .pc-warn { color: var(--garment-designer-red); }
  .pc-note { color: var(--text-dim); }
  .pw-row { display: flex; align-items: center; gap: 6px; font-size: 12px; margin: 6px 0; }

  .pw-row input {
    width: 58px;
    padding: 4px 6px;
    border: 1px solid var(--border);
    border-radius: 6px;
    font-size: 12px;
    font-weight: 600;
  }

  /* Print-location preset chips */
  .loc-chips { display: flex; flex-wrap: wrap; gap: 4px; margin: 4px 0 7px; }

  .loc-chip {
    font-size: 10px; font-weight: 700;
    padding: 3px 9px;
    border-radius: 12px;
    border: 1px solid var(--border);
    background: var(--color-surface);
    cursor: pointer;
  }
  .loc-chip.active { background: var(--brand); color: var(--color-on-brand); border-color: var(--brand); }

  /* Spec sheet (only visible when printing) */
  #specSheet { display: none; }

  @media print {
    body.print-spec header, body.print-spec main, body.print-spec footer, body.print-spec #dragOverlay, body.print-spec #toast { display: none !important; }
    body.print-spec #specSheet { display: block !important; }
  }
  #specSheet { font-family: 'Segoe UI', system-ui, Arial, sans-serif; color: var(--store-ink); padding: 28px; }
  #specSheet .sp-head { display: flex; justify-content: space-between; align-items: flex-start; border-bottom: 3px solid var(--brand-700); padding-bottom: 10px; margin-bottom: 16px; }
  #specSheet h1 { font-size: 20px; margin: 0; color: var(--brand-700); }
  #specSheet .sp-sub { font-size: 12px; color: var(--print-ink-soft); }
  #specSheet .sp-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 4px 24px; font-size: 13px; margin-bottom: 14px; }
  #specSheet .sp-grid b { color: var(--gray-700); font-weight: 700; }
  #specSheet table { width: 100%; border-collapse: collapse; margin: 8px 0 14px; }
  #specSheet th, #specSheet td { border: 1px solid var(--garment-designer-gray); padding: 5px 8px; font-size: 12px; text-align: left; }
  #specSheet th { background: var(--brand-100); }
  #specSheet .sp-swatch { display: inline-block; width: 14px; height: 14px; border: 1px solid var(--print-line); border-radius: 3px; vertical-align: -2px; margin-right: 6px; }
  #specSheet .sp-thumb { max-width: 320px; max-height: 320px; border: 1px solid var(--gray-300); }
  #specSheet .sp-flags { font-size: 12px; line-height: 1.6; }
  #specSheet .sp-foot { margin-top: 18px; font-size: 11px; color: var(--garment-designer-gray-3); border-top: 1px solid var(--gray-300); padding-top: 8px; }

  /* PC61 color drawer */
  #colorDrawer {
    display: none;
    flex-wrap: wrap;
    gap: 6px;
    padding: 10px 14px;
    background: var(--panel);
    border-bottom: 1px solid var(--border);
    max-height: 170px;
    overflow-y: auto;
    flex-shrink: 0;
  }
  #colorDrawer.visible { display: flex; }

  .pcsw {
    width: 26px; height: 26px;
    border-radius: 50%;
    border: 2px solid var(--border);
    cursor: pointer;
    padding: 0;
    flex-shrink: 0;
  }
  .pcsw.active { border-color: var(--brand); box-shadow: 0 0 0 2px var(--brand-light); }
  #drawerLabel { width: 100%; font-size: 11px; font-weight: 700; color: var(--text-dim); }

  /* Toast */
  #toast {
    position: fixed;
    bottom: 34px; left: 50%;
    transform: translateX(-50%);
    background: var(--brand-dark);
    color: var(--color-on-brand);
    padding: 8px 16px;
    border-radius: 8px;
    font-size: 12px; font-weight: 600;
    z-index: 300;
    opacity: 0;
    pointer-events: none;
    transition: opacity .25s;
  }
  #toast.show { opacity: 1; }

  /* A sticky toast carrying an action (e.g. "Undo") must be clickable — the base
     toast is pointer-events:none. */
  #toast.has-action { pointer-events: auto; }

  .toast-action {
    margin-left: 12px;
    background: rgb(255 255 255 / 14%);
    border: 1px solid rgb(255 255 255 / 70%);
    color: var(--color-on-brand);
    border-radius: 6px;
    padding: 3px 10px;
    font-size: 12px;
    font-weight: 800;
    cursor: pointer;
  }
  .toast-action:hover { background: rgb(255 255 255 / 28%); }

  /* Amber low-contrast warning chip shown in the toolbar when the art may be hard
     to see on the chosen shirt color (e.g. white art on a white shirt). */
  .contrast-warn {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    background: var(--store-paper-deep);
    border: 1px solid var(--garment-designer-yellow);
    color: var(--garment-designer-yellow-dark-2);
    border-radius: 8px;
    padding: 6px 10px;
    font-size: 12px;
    font-weight: 800;
    white-space: nowrap;
  }

  /* Accessibility: keyboard focus was invisible across the whole tool. Give every
     interactive control a clear, consistent focus ring. */
  button:focus-visible,
  a:focus-visible,
  input:focus-visible,
  select:focus-visible,
  [tabindex]:focus-visible {
    outline: 3px solid var(--brand);
    outline-offset: 2px;
    border-radius: 6px;
  }

  /* Phase 2 — Send to Steve / Send to Customer toolbar buttons */
  .easy-main-btn.send-steve {
    background: var(--garment-designer-blue); color: var(--color-on-brand); border-color: var(--garment-designer-blue);
  }
  .easy-main-btn.send-steve:hover { background: var(--indigo-700); border-color: var(--indigo-700); }

  .easy-main-btn.send-customer {
    background: var(--blue-600); color: var(--color-on-brand); border-color: var(--blue-600);
  }
  .easy-main-btn.send-customer:hover { background: var(--color-floor-dark); border-color: var(--color-floor-dark); }

  /* Phase 2 — designer modals (Send to Steve form host + Send to Customer email) */
  .ds-modal-overlay {
    display: none;
    position: fixed; inset: 0;
    background: rgb(15 25 10 / 55%);
    z-index: 1000;
    align-items: flex-start; justify-content: center;
    padding: 28px 16px; overflow-y: auto;
  }
  .ds-modal-overlay.open { display: flex; }

  .ds-modal-card {
    background: var(--color-surface); border-radius: 14px;
    box-shadow: 0 18px 60px rgb(10 20 8 / 35%);
    width: 100%; max-width: 460px; margin: auto;
    display: flex; flex-direction: column;
  }
  .ds-modal-card.ds-modal-wide { max-width: 940px; }

  .ds-modal-head {
    display: flex; align-items: center; justify-content: space-between;
    padding: 16px 20px; border-bottom: 1px solid var(--border);
  }
  .ds-modal-head h3 { margin: 0; font-size: 16px; color: var(--text); }

  .ds-modal-close {
    border: none; background: none; font-size: 26px; line-height: 1;
    color: var(--text-dim); cursor: pointer; padding: 0 4px;
  }
  .ds-modal-close:hover { color: var(--text); }
  .ds-modal-intro { padding: 12px 20px 0; font-size: 13px; color: var(--text-dim); line-height: 1.5; }
  .ds-modal-body { padding: 16px 20px; }
  .ds-modal-wide .ds-modal-body { max-height: 72vh; overflow-y: auto; }

  .ds-modal-foot {
    display: flex; justify-content: flex-end; gap: 10px;
    padding: 14px 20px; border-top: 1px solid var(--border);
  }
  .ds-field { margin-bottom: 14px; }
  .ds-field label { display: block; font-size: 12px; font-weight: 800; color: var(--text); margin-bottom: 5px; }
  .ds-req { color: var(--garment-designer-red-2); }

  .ds-field input, .ds-field textarea {
    width: 100%; box-sizing: border-box;
    border: 1px solid var(--border); border-radius: 9px;
    padding: 9px 11px; font-size: 13px; font-family: inherit; color: var(--text);
  }
  .ds-field textarea { resize: vertical; }
  .ds-modal-note { font-size: 12px; color: var(--text-dim); line-height: 1.5; margin-top: 4px; }

  .ds-btn-ghost {
    border: 1px solid var(--border); background: var(--color-surface); color: var(--text);
    border-radius: 9px; padding: 9px 16px; font-size: 13px; font-weight: 800; cursor: pointer;
  }
  .ds-btn-ghost:hover { background: var(--brand-light); }

  .ds-btn-primary {
    border: 1px solid var(--blue-600); background: var(--blue-600); color: var(--color-on-brand);
    border-radius: 9px; padding: 9px 18px; font-size: 13px; font-weight: 800; cursor: pointer;
  }
  .ds-btn-primary:hover { background: var(--color-floor-dark); }
  .ds-btn-primary:disabled, .ds-btn-ghost:disabled { opacity: .6; cursor: default; }
  #canvasHolder canvas, #canvasHolder img { display: block; }

  /* Drop zone / empty state */
  #dropzone {
    position: absolute;
    inset: 0;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: 14px;
    text-align: center;
    padding: 24px;
    background: var(--bg);
    z-index: 5;
  }
  #dropzone.hidden { display: none; }

  .dz-icon {
    width: 84px; height: 84px;
    border-radius: 20px;
    background: var(--brand-light);
    border: 2px dashed var(--brand-mid);
    display: flex; align-items: center; justify-content: center;
  }
  .dz-icon svg { width: 40px; height: 40px; stroke: var(--brand); }
  #dropzone h2 { font-size: 20px; color: var(--text); }
  #dropzone p { font-size: 13px; color: var(--text-dim); max-width: 420px; line-height: 1.5; }
  .formats { display: flex; gap: 6px; flex-wrap: wrap; justify-content: center; }

  .fmt {
    font-size: 11px; font-weight: 800;
    padding: 3px 9px;
    border-radius: 20px;
    background: var(--brand); color: var(--color-on-brand);
  }
  .fmt.dim { background: var(--print-line); }

  /* Drag-over overlay */
  #dragOverlay {
    position: fixed; inset: 0;
    background: rgb(47 102 30 / 92%);
    color: var(--color-on-brand);
    display: none;
    align-items: center; justify-content: center;
    flex-direction: column;
    gap: 10px;
    z-index: 100;
    font-size: 22px; font-weight: 700;
    pointer-events: none;
  }
  #dragOverlay.visible { display: flex; }
  #dragOverlay .small { font-size: 13px; font-weight: 400; opacity: .8; }

  /* Loading / error overlays on stage */
  #stageMsg {
    position: absolute; inset: 0;
    display: none;
    align-items: center; justify-content: center;
    flex-direction: column;
    gap: 12px;
    background: rgb(244 246 242 / 96%);
    z-index: 4;
    text-align: center;
    padding: 24px;
  }
  #stageMsg.visible { display: flex; }

  .spinner {
    width: 38px; height: 38px;
