/* ============================================================
   Phase 3 — responsive (tablet + phone)
   The 3-column layout (#sidebar | #stage | #infoPanel) has fixed
   widths down to 1400px, so on an iPad portrait the two side
   panels (≈640px) crush the stage. Trim at landscape-tablet,
   then stack everything vertically with natural page scroll.
   ============================================================ */

/* Landscape iPad (~1024px): shrink the side panels so the stage stays usable */
@media (width <= 1180px) {
  body.left-controls-layout #sidebar { width: 270px; min-width: 270px; max-width: 270px; }
  body.left-controls-layout #infoPanel { width: 250px; min-width: 250px; max-width: 250px; }
}

/* Tablet portrait + phone (≤900px): stack the columns, scroll the page */
@media (width <= 900px) {
  html, body { height: auto; }
  body { min-height: 100vh; }
  main { flex-direction: column; flex: 0 0 auto; min-height: 0; }

  /* toolbar + shirt first, controls below */
  #viewerCol { order: 0; flex: 0 0 auto; }

  body.left-controls-layout #sidebar,
  #sidebar.visible {
    order: 2;
    width: 100%; min-width: 0; max-width: none;
    flex: 0 0 auto;
    height: auto; max-height: none; overflow: visible;
    border-right: none; border-top: 1px solid var(--border);
  }
  body.left-controls-layout #fileList { max-height: 150px; }
  body.left-controls-layout #leftControlsMount { overflow: visible; }

  /* stage above the advisor panel; give the canvas a real height */
  #stageWrap { flex-direction: column; flex: 0 0 auto; min-height: 0; }
  #stage { flex: 0 0 auto; height: 60vh; min-height: 320px; }

  #infoPanel,
  body.left-controls-layout #infoPanel,
  body.clean-layout #infoPanel {
    width: 100%; min-width: 0; max-width: none;
    flex: 0 0 auto;
    overflow: visible;
    border-left: none; border-top: 1px solid var(--border);
  }
  #infoPanel.visible { display: flex; }

  /* touch-sized controls */
  #toolbar { gap: 8px; }
  .easy-main-btn, .details-btn, .ds-btn-primary, .ds-btn-ghost { min-height: 40px; }
}

/* Phone (≤560px): trim chrome + full-bleed modals */
@media (width <= 560px) {
  header { padding: 8px 12px; }
  .privacy-note { display: none; }
  .easy-status { display: none; }   /* the step hint otherwise eats a whole toolbar row */

  /* one swipeable row of actions instead of an 8-row wrap that buries the shirt */
  #toolbar { flex-wrap: nowrap; overflow: auto hidden; -webkit-overflow-scrolling: touch; }

  #toolbar .easy-main-btn, #toolbar .details-btn, #toolbar .fabric-select {
    flex: 0 0 auto; padding: 8px 11px; font-size: 12px;
  }
  #stage { height: 52vh; min-height: 280px; }
  .ds-modal-overlay { padding: 12px 8px; }
  .ds-modal-card, .ds-modal-card.ds-modal-wide { max-width: 100%; }
}

/* ============================================================
   Text editor panel — docked card, updates the mockup live
   ============================================================ */
.text-panel {
  display: none;
  position: fixed;
  left: 14px; top: 116px; bottom: 16px;
  width: 300px; max-width: calc(100vw - 28px);
  background: var(--color-surface);
  border: 1px solid var(--border);
  border-radius: 14px;
  box-shadow: 0 18px 50px rgb(10 20 8 / 28%);
  z-index: 600;
  flex-direction: column;
  overflow: hidden;
}
.text-panel.open { display: flex; }

.tp-head {
  display: flex; align-items: center; justify-content: space-between;
  padding: 12px 14px; border-bottom: 1px solid var(--border);
  font-weight: 800; font-size: 14px; color: var(--text);
}
.tp-x { border: none; background: none; font-size: 22px; line-height: 1; color: var(--text-dim); cursor: pointer; }
.tp-x:hover { color: var(--text); }
.tp-body { padding: 12px 14px; overflow-y: auto; flex: 1; display: flex; flex-direction: column; gap: 11px; }

.tp-text {
  width: 100%; box-sizing: border-box; resize: vertical;
  border: 1px solid var(--border); border-radius: 9px; padding: 9px 10px;
  font-size: 14px; font-family: inherit; color: var(--text); min-height: 46px;
}
.tp-font { width: 100%; box-sizing: border-box; border: 1px solid var(--border); border-radius: 9px; padding: 8px 10px; font-size: 14px; background: var(--color-surface); }
.tp-row { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }

.tp-toggle {
  width: 36px; height: 34px; border: 1px solid var(--border); background: var(--color-surface); border-radius: 8px;
  font-size: 15px; cursor: pointer; color: var(--text);
}
.tp-toggle.on { background: var(--brand); color: var(--color-on-brand); border-color: var(--brand); }
.tp-seg { display: inline-flex; border: 1px solid var(--border); border-radius: 8px; overflow: hidden; }
.tp-seg-wide { width: 100%; }

.tp-seg-btn {
  flex: 1; min-width: 34px; height: 34px; border: none; background: var(--color-surface); cursor: pointer;
  font-size: 13px; font-weight: 800; color: var(--text-dim); border-right: 1px solid var(--border);
}
.tp-seg-btn:last-child { border-right: none; }
.tp-seg-btn.on { background: var(--brand-light); color: var(--brand-dark); }
.tp-field { display: flex; flex-direction: column; gap: 5px; }
.tp-field.tp-inline { flex-flow: row wrap; align-items: center; gap: 10px; }
.tp-field label { font-size: 12px; font-weight: 700; color: var(--text); display: flex; align-items: center; gap: 6px; }
.tp-field label span { color: var(--text-dim); font-weight: 800; }
.tp-field input[type="range"] { width: 100%; flex: 1; }
.tp-field input[type="color"] { width: 40px; height: 30px; border: 1px solid var(--border); border-radius: 7px; padding: 2px; cursor: pointer; background: var(--color-surface); }
.tp-foot { display: flex; justify-content: space-between; gap: 10px; padding: 12px 14px; border-top: 1px solid var(--border); }
.tp-del { border: 1px solid var(--garment-designer-red-3); background: var(--color-surface); color: var(--garment-designer-red); border-radius: 9px; padding: 8px 14px; font-weight: 800; font-size: 13px; cursor: pointer; }
.tp-del:hover { background: var(--store-rush-soft); }
.tp-done { border: 1px solid var(--brand); background: var(--brand); color: var(--color-on-brand); border-radius: 9px; padding: 8px 18px; font-weight: 800; font-size: 13px; cursor: pointer; }
.tp-done:hover { background: var(--brand-dark); }

@media (width <= 900px) {
  .text-panel { inset: auto 0 0; width: 100%; max-width: none; max-height: 64vh; border-radius: 14px 14px 0 0; }
}

/* Toolbar workflow groups (ADD / STYLE / PREVIEW / DELIVER / DETAILS), separated
   by the existing .easy-divider. On narrow screens groups dissolve so buttons
   flow/wrap as direct toolbar children (preserves the mobile single-row swipe). */
.tb-group { display: inline-flex; align-items: center; gap: 8px; flex-wrap: wrap; }

@media (width <= 900px) {
  .tb-group { display: contents; }
  #toolbar > .easy-divider { display: none; }
}

/* ============================================================
   2026-08-04 — Guided workflow declutter
   One entry point (the landing hero). Chrome reveals as the mockup
   progresses: garment-designer.js sets body.has-art whenever the
   entries[] list is non-empty (updateWorkflowState). Until then the
   page shows only the Add + Shirt toolbar groups and the landing —
   no disabled placement rail, no empty "—" advisors, no send buttons
   for a mockup that doesn't exist yet.
   ============================================================ */

/* Empty state: hide everything that can't act on artwork yet */
body:not(.has-art) .tb-group.needs-art { display: none; }
body:not(.has-art) #sidebar { display: none; }
body.left-controls-layout:not(.has-art) #sidebar { display: none; }
body:not(.has-art) #infoPanel { display: none !important; }

/* Labeled toolbar groups — the button wall becomes a scannable map */
#toolbar .tb-group[data-label] {
  position: relative;
  border: 1px solid var(--store-green-100);
  background: var(--gray-50);
  border-radius: 12px;
  padding: 17px 9px 7px;
  gap: 7px;
}

#toolbar .tb-group[data-label]::before {
  content: attr(data-label);
  position: absolute;
  top: 3px;
  left: 10px;
  font-size: 9px;
  font-weight: 900;
  letter-spacing: .09em;
  text-transform: uppercase;
  color: var(--store-ink-faint);
  pointer-events: none;
}

@media (width <= 900px) {
  /* groups dissolve to display:contents here — a positioned label would float loose */
  #toolbar .tb-group[data-label]::before { display: none; }
}

/* Landing hero: upload cards are real <button>s now */
button.easy-upload-card { font: inherit; width: 100%; }

.easy-text-start {
  display: block;
  width: 100%;
  margin-top: 12px;
  padding: 10px 14px;
  border: 1px solid var(--border);
  border-radius: 12px;
  background: var(--color-surface);
  font: inherit;
  font-size: 13px;
  font-weight: 700;
  color: var(--text);
  cursor: pointer;
}
.easy-text-start:hover { background: var(--brand-light); border-color: var(--brand-mid); }

.easy-formats {
  margin-top: 14px;
  font-size: 12px;
  color: var(--text-dim);
  line-height: 1.5;
}

/* Fabric input lives with the advice it feeds (Print Method Advisor) */
.advisor-fabric-row {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-top: 10px;
}

.advisor-fabric-row label {
  font-size: 11px;
  font-weight: 800;
  color: var(--text-dim);
  white-space: nowrap;
}
.advisor-fabric-row .fabric-select { flex: 1; min-width: 0; }

/* Multi-page PDF navigation — floats over the stage (it previously sat
   inside .easy-hidden-tools where display:none made it unreachable) */
#pageNav.stage-pagenav {
  position: absolute;
  left: 50%;
  transform: translateX(-50%);
  bottom: 14px;
  z-index: 30;
  background: var(--color-surface);
  border: 1px solid var(--border);
  border-radius: 999px;
  padding: 4px 8px;
  box-shadow: 0 6px 18px rgb(18 34 11 / 15%);
}

/* Per-file remove — uploads were previously permanent for the session */
.file-x {
  flex: 0 0 auto;
  width: 22px;
  height: 22px;
  border: 1px solid var(--border);
  border-radius: 50%;
  background: var(--color-surface);
  color: var(--text-dim);
  font-size: 14px;
  line-height: 1;
  font-weight: 700;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0;
}
.file-x:hover { background: var(--red-100); border-color: var(--garment-designer-red-4); color: var(--red-700); }

