changes.before:
function renderInfo(entry) {
  const rows = $('infoRows');
  rows.innerHTML = '';
  const add = (k, v) => {
    const d = document.createElement('div');
    d.className = 'info-row';
    d.innerHTML = '<div class="k">' + escapeHtml(k) + '</div><div class="v">' + escapeHtml(String(v)) + '</div>';
    rows.appendChild(d);
  };
  add('File name', entry.name);
  for (const [k, v] of Object.entries(entry.info || {})) add(k, v);
  if (entry.kind === 'pdf' && entry.pageCount > 1) add('Viewing', 'Page ' + entry.pageNum + ' of ' + entry.pageCount);

  // ---- Ink colors / separations ----
  if (entry.palette && entry.palette.length && entry.status === 'ready') {
    const d = document.createElement('div');
    d.className = 'info-row';
    let rowsHtml = '';
    entry.palette.forEach((c, i) => {
      const pms = nearestPMS(c.r, c.g, c.b);
      const pmsTxt = pms.close ? '≈ PMS ' + pms.name : '(no close PMS match)';
      rowsHtml += '<div class="ink-row' + (entry.sepIndex === i ? ' active' : '') + '" data-idx="' + i + '" title="Click to preview this screen alone">'
        + '<span class="sw" style="background:' + c.hex + '"></span>'
        + '<span class="ink-meta"><span class="ink-hex" data-hex="' + c.hex + '" title="Click to copy">' + c.hex + '</span> · ' + c.pct + '%'
        + '<br><span class="ink-pms">' + escapeHtml(pmsTxt) + '</span></span>'
        + '</div>';
    });
