/* garment-submit-form.css
 * Garment art-request form (GarmentSubmitForm) on dashboards/ae-dashboard.html
 * (Submit Artwork to Steve → Garment). Class prefix: .gsf-*
 * 
 * Design language is shared by construction with sticker-banner-, jds- and
 * mockup-submit-form.css: identical field / drop-zone / rush / submit /
 * success / toast rules, only the --fx-* accent tokens differ. Keep the
 * four in step when editing a shared block (Rule 8 spirit).
 * Also linked by pages/garment-designer.html (uses none of the classes).
 */

/* Page theme (CSS standardization, 2026-09-07): this page's own colours, auto-named by hue so the page
   keeps its exact look. Map them to shared_components/css/tokens.css names when the page is redesigned;
   every rule below uses var(). Raw hex is allowed ONLY in this block. */
/* stylelint-disable color-no-hex */
:root {
    --garment-submit-form-green-tint: #cdf3d6;
    --garment-submit-form-teal-dark-2: #064e3b;
    --garment-submit-form-orange: #6b4423;
    --garment-submit-form-orange-2: #a1703f;
    --garment-submit-form-orange-4: #7c2d12;
    --garment-submit-form-orange-5: #f97316;
}
/* stylelint-enable color-no-hex */

/* ── Scoped design tokens ───────────────────────────────────────────────
   Every visual constant the form uses lives here so a colour change is one
   edit. --fx-* names are shared by all four intake forms (gsf/sbf/jds/msf);
   only the values differ per form. */
.gsf-container {
    --fx-accent:       var(--color-steve);
    --fx-accent-dark:  var(--color-steve-dark);
    --fx-accent-light: var(--color-steve-light);
    --fx-tint:         var(--color-steve-tint);
    --fx-tint-2:       var(--garment-submit-form-green-tint);
    --fx-ring:         rgb(10 138 31 / 16%);
    --fx-grad:         linear-gradient(135deg, var(--fx-accent-dark) 0%, var(--fx-accent) 55%, var(--fx-accent-light) 100%);

    max-width: 1020px;
    margin: 0 auto;
    font-family: inherit;
    color: var(--gray-800, var(--gray-800));
}

/* ── Hero banner ────────────────────────────────────────────────────── */
.gsf-banner {
    position: relative;
    isolation: isolate;
    overflow: hidden;
    display: flex;
    align-items: center;
    gap: 20px;
    padding: 24px 28px;
    border-radius: 18px;
    margin-bottom: 20px;
    color: var(--color-on-brand);
    background: var(--fx-grad);
    box-shadow: 0 18px 40px -18px color-mix(in srgb, var(--fx-accent) 75%, transparent),
                0 2px 6px rgb(15 23 42 / 6%);
}

.gsf-banner::before {
    content: '';
    position: absolute;
    inset: 0;
    z-index: -1;
    background:
        radial-gradient(circle at 88% 12%, rgb(255 255 255 / 22%), transparent 42%),
        radial-gradient(circle at 8% 120%, rgb(255 255 255 / 12%), transparent 40%);
    pointer-events: none;
}

.gsf-banner::after {
    content: '';
    position: absolute;
    right: -48px;
    top: -70px;
    width: 240px;
    height: 240px;
    border-radius: 50%;
    border: 30px solid rgb(255 255 255 / 7%);
    z-index: -1;
    pointer-events: none;
}

.gsf-banner-emoji {
    flex: 0 0 auto;
    width: 66px;
    height: 66px;
    border-radius: 18px;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 34px;
    line-height: 1;
    background: rgb(255 255 255 / 16%);
    border: 1px solid rgb(255 255 255 / 30%);
    box-shadow: inset 0 1px 0 rgb(255 255 255 / 30%), 0 10px 22px -10px rgb(0 0 0 / 40%);
    backdrop-filter: blur(6px);
}
.gsf-banner-text { min-width: 0; }

.gsf-banner-text::before {
    content: 'Steve · Graphic Arts';
    display: block;
    font-size: 11px;
    font-weight: 700;
    letter-spacing: .12em;
    text-transform: uppercase;
    color: rgb(255 255 255 / 74%);
    margin-bottom: 6px;
}

.gsf-banner-text h3 {
    margin: 0 0 6px;
    font-size: 22px;
    font-weight: 800;
    letter-spacing: -.02em;
    line-height: 1.2;
}

.gsf-banner-text p {
    margin: 0;
    font-size: 14px;
    line-height: 1.55;
    color: rgb(255 255 255 / 88%);
    max-width: 660px;
}

/* ── Form card ──────────────────────────────────────────────────────── */
.gsf-form-card {
    background: var(--color-surface);
    border: 1px solid var(--gray-200, var(--gray-200));
    border-radius: 18px;
    box-shadow: var(--shadow-md, 0 2px 4px rgb(15 23 42 / 4%), 0 4px 12px rgb(15 23 42 / 6%));
}

.gsf-form-body { padding: 6px 32px 28px; }

/* ── Field grid ─────────────────────────────────────────────────────── */
.gsf-row {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 0 20px;
}

.gsf-field {
    display: flex;
    flex-direction: column;
    gap: 6px;
    margin-bottom: 18px;
    min-width: 0;
}

.gsf-label {
    display: flex;
    align-items: center;
    gap: 4px;
    font-size: 13px;
    font-weight: 600;
