}
.gsf-req { color: var(--fx-accent); font-weight: 700; }

.gsf-hint {
    font-size: 12px;
    color: var(--gray-500, var(--gray-500));
    line-height: 1.45;
    margin-top: 2px;
}

/* Inputs — one height, one radius, one focus ring */
.gsf-input,
.gsf-select,
.gsf-textarea {
    width: 100%;
    box-sizing: border-box;
    min-height: 42px;
    padding: 10px 13px;
    border: 1px solid var(--gray-300, var(--gray-300));
    border-radius: 10px;
    font-size: 14px;
    font-family: inherit;
    color: var(--gray-900, var(--gray-900));
    background-color: var(--color-on-brand);
    box-shadow: 0 1px 2px rgb(15 23 42 / 4%);
    transition: border-color .15s ease, box-shadow .15s ease, background-color .15s ease;
}

.gsf-input:hover,
.gsf-select:hover,
.gsf-textarea:hover { border-color: var(--gray-400, var(--gray-400)); }

.gsf-input:focus,
.gsf-select:focus,
.gsf-textarea:focus {
    outline: none;
    border-color: var(--fx-accent);
    box-shadow: 0 0 0 4px var(--fx-ring), 0 1px 2px rgb(15 23 42 / 4%);
}

.gsf-input::placeholder,
.gsf-textarea::placeholder { color: var(--gray-400, var(--gray-400)); }

.gsf-select {
    appearance: none;
    padding-right: 38px;
    cursor: pointer;
    background-image: url("data:image/svg+xml;charset=utf-8,%3Csvg xmlns='http://www.w3.org/2000/svg' width='16' height='16' viewBox='0 0 24 24' fill='none' stroke='%236b7280' stroke-width='2.2' stroke-linecap='round' stroke-linejoin='round'%3E%3Cpolyline points='6 9 12 15 18 9'/%3E%3C/svg%3E");
    background-repeat: no-repeat;
    background-position: right 12px center;
    background-size: 16px;
}

.gsf-input:disabled,
.gsf-select:disabled,
.gsf-input[readonly] {
    background-color: var(--gray-50, var(--gray-50));
    color: var(--gray-500, var(--gray-500));
    cursor: not-allowed;
    box-shadow: none;
}

.gsf-textarea {
    min-height: 96px;
    resize: vertical;
    line-height: 1.5;
}

.gsf-input.gsf-error,
.gsf-select.gsf-error,
.gsf-textarea.gsf-error {
    border-color: var(--state-danger, var(--red-600));
    background-color: var(--state-danger-bg, var(--red-50));
    box-shadow: 0 0 0 4px rgb(220 38 38 / 10%);
}

.gsf-err {
    display: none;
    font-size: 12.5px;
    font-weight: 500;
    color: var(--state-danger, var(--red-600));
    margin-top: 2px;
    line-height: 1.4;
}

/* ── File drop zone ─────────────────────────────────────────────────── */
.gsf-file-drop {
    position: relative;
    padding: 28px 20px 22px;
    border: 2px dashed var(--gray-300, var(--gray-300));
    border-radius: 16px;
    text-align: center;
    cursor: pointer;
    color: var(--gray-500, var(--gray-500));
    font-size: 14px;
    background: linear-gradient(180deg, var(--color-surface) 0%, var(--gray-50, var(--gray-50)) 100%);
    transition: border-color .2s ease, background .2s ease, box-shadow .2s ease, transform .2s ease;
}

.gsf-file-drop:hover,
.gsf-file-drop--active {
    border-color: var(--fx-accent);
    background: linear-gradient(180deg, var(--color-surface) 0%, var(--fx-tint) 100%);
    box-shadow: 0 0 0 4px var(--fx-ring);
}
.gsf-file-drop--active { transform: scale(1.004); }

.gsf-file-drop-icon {
    width: 52px;
    height: 46px;
    margin: 0 auto 10px;
    display: block;
    color: var(--gray-400, var(--gray-400));
    transition: transform .25s var(--ease-out, cubic-bezier(.2,.8,.2,1));
}

.gsf-file-drop:hover .gsf-file-drop-icon,
.gsf-file-drop--active .gsf-file-drop-icon { transform: translateY(-3px); }

.gsf-file-drop-cta {
    font-size: 15.5px;
    font-weight: 700;
    color: var(--gray-800, var(--gray-800));
}

.gsf-file-drop-sub {
    font-size: 13px;
    color: var(--gray-500, var(--gray-500));
    margin: 4px 0 12px;
}

.gsf-file-drop-dots {
    display: flex;
    justify-content: center;
    gap: 8px;
}

.gsf-file-drop-dot {
    width: 10px;
    height: 10px;
    border-radius: 50%;
    background: transparent;
    border: 2px solid var(--gray-300, var(--gray-300));
    transition: background .2s ease, border-color .2s ease, transform .2s ease, box-shadow .2s ease;
}

.gsf-file-drop-dot--filled {
    background: var(--state-success, var(--emerald-600));
    border-color: var(--state-success, var(--emerald-600));
