}

.gsf-file-drop-types {
    font-size: 12px;
    color: var(--gray-500, var(--gray-500));
    text-align: center;
    margin-top: 10px;
}

/* Capacity reached — reads as "no more room", hover neutralised */
.gsf-file-drop--full {
    opacity: .55;
    cursor: not-allowed;
    background: var(--gray-100, var(--gray-100));
}

.gsf-file-drop--full:hover,
.gsf-file-drop--full.gsf-file-drop--active {
    border-color: var(--gray-300, var(--gray-300));
    background: var(--gray-100, var(--gray-100));
