}

.gsf-file-size {
    color: var(--gray-500, var(--gray-500));
    font-size: 12px;
    flex: 0 0 auto;
    font-variant-numeric: tabular-nums;
}

.gsf-file-remove {
    width: 26px;
    height: 26px;
    border-radius: 50%;
