}

@keyframes gsf-rush-flicker {
    0%, 100% { transform: scale(1); }
    50%      { transform: scale(1.18); }
}

/* ── Submit ─────────────────────────────────────────────────────────── */
.gsf-submit-row {
    display: flex;
    align-items: center;
    gap: 16px;
    flex-wrap: wrap;
    padding-top: 22px;
