/* ── Success ────────────────────────────────────────────────────────── */
.gsf-success {
    text-align: center;
    padding: 56px 20px 48px;
    animation: gsf-fade-up .4s var(--ease-out, cubic-bezier(.2,.8,.2,1));
}

.gsf-success-icon {
    width: 92px;
    height: 92px;
    margin: 0 auto 20px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 44px;
    line-height: 1;
    background: var(--state-success-bg, var(--brand-50));
    box-shadow: 0 0 0 10px rgb(5 150 105 / 8%), 0 0 0 20px rgb(5 150 105 / 4%);
    animation: gsf-pop .55s cubic-bezier(.2, .8, .2, 1);
}

.gsf-success h3 {
    margin: 0 0 10px;
    font-size: 24px;
    font-weight: 800;
    letter-spacing: -.02em;
    color: var(--gray-900, var(--gray-900));
}

.gsf-success-id {
    display: inline-block;
    margin-left: 6px;
    padding: 3px 12px;
    border-radius: 999px;
    background: var(--fx-tint);
    color: var(--fx-accent);
    font-size: 15px;
    font-weight: 700;
    vertical-align: middle;
}

.gsf-success p {
    color: var(--gray-600, var(--gray-600));
    line-height: 1.6;
    margin: 0 auto 24px;
    max-width: 480px;
    font-size: 14.5px;
}

.gsf-success-link {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    padding: 11px 22px;
    margin: 0 8px 8px 0;
    background: var(--state-success, var(--emerald-600));
    color: var(--color-on-brand);
    text-decoration: none;
    border-radius: 10px;
    font-weight: 700;
    font-size: 14px;
    box-shadow: 0 8px 18px -8px rgb(5 150 105 / 70%);
    transition: background .15s ease, transform .15s ease;
}
.gsf-success-link:hover { background: var(--emerald-700); transform: translateY(-1px); }

.gsf-success-another {
    padding: 11px 22px;
    background: var(--color-surface);
    color: var(--fx-accent);
    border: 1.5px solid var(--fx-accent);
    border-radius: 10px;
    font-size: 14px;
    font-weight: 700;
    cursor: pointer;
    font-family: inherit;
    transition: background .15s ease, color .15s ease;
}
.gsf-success-another:hover { background: var(--fx-accent); color: var(--color-on-brand); }

@keyframes gsf-pop {
    0%   { transform: scale(.4); opacity: 0; }
    60%  { transform: scale(1.08); opacity: 1; }
    100% { transform: scale(1); }
}

@keyframes gsf-fade-up {
    from { opacity: 0; transform: translateY(8px); }
    to   { opacity: 1; transform: none; }
}

/* ── Toast (mounted on <body>, so colours are literal, not --fx-*) ──── */
.gsf-toast {
    position: fixed;
    bottom: 24px;
    left: 50%;
    transform: translateX(-50%) translateY(16px);
    padding: 12px 20px 12px 16px;
    border-radius: 12px;
    border-left: 4px solid transparent;
    color: var(--color-on-brand);
    font-weight: 500;
    font-size: 14px;
    box-shadow: 0 12px 32px -8px rgb(15 23 42 / 45%);
    opacity: 0;
    transition: opacity .25s ease, transform .25s ease;
    z-index: 9999;
    max-width: 80%;
    text-align: center;
}
.gsf-toast.show { opacity: 1; transform: translateX(-50%) translateY(0); }
.gsf-toast--info    { background: var(--gray-800); border-left-color: var(--color-steve); }
.gsf-toast--error   { background: var(--red-600); border-left-color: var(--print-red); }
.gsf-toast--success { background: var(--emerald-600); border-left-color: var(--garment-submit-form-teal-dark-2); }

/* ── Numbered sections on a stepper rail ───────────────────────────────
   Each section is a node on a vertical rail: the number badge sits in the
   left gutter and a 2px line links it to the next section. */
.gsf-section {
    position: relative;
    padding: 22px 0 22px 48px;
}

.gsf-section::before {
    content: '';
    position: absolute;
    left: 14px;
    top: 54px;
    bottom: -2px;
    width: 2px;
    background: linear-gradient(180deg, var(--gray-200, var(--gray-200)), var(--gray-200, var(--gray-200)) 70%, transparent);
}
.gsf-section:last-of-type::before { display: none; }

.gsf-section-head {
    display: flex;
    align-items: center;
    gap: 10px;
    min-height: 30px;
    margin-bottom: 4px;
}

.gsf-section-num,
.gsf-patch-badge {
    position: absolute;
    left: 0;
    top: 22px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 30px;
    height: 30px;
    border-radius: 50%;
    background: var(--fx-grad);
    color: var(--color-on-brand);
    font-size: 13px;
    font-weight: 800;
    letter-spacing: -.02em;
    box-shadow: 0 0 0 4px var(--color-surface), 0 0 0 5px var(--gray-200, var(--gray-200)), 0 6px 14px -6px color-mix(in srgb, var(--fx-accent) 70%, transparent);
    z-index: 1;
}

.gsf-section-title {
    font-size: 16px;
    font-weight: 700;
    color: var(--gray-900, var(--gray-900));
    letter-spacing: -.01em;
}

.gsf-section-hint {
    font-size: 13px;
    color: var(--gray-500, var(--gray-500));
    margin: 0 0 16px;
    line-height: 1.5;
    max-width: 720px;
}

.gsf-section .gsf-row:last-child .gsf-field,
.gsf-section > .gsf-field:last-child { margin-bottom: 0; }

/* Section that becomes required (repeat / revision) — amber spotlight */
.gsf-section--required {
    background: linear-gradient(180deg, var(--store-paper) 0%, var(--store-rush-soft) 100%);
    border: 1px solid var(--amber-200);
    border-radius: 14px;
    margin: 6px -16px;
    padding: 22px 16px 22px 64px;
    box-shadow: 0 0 0 4px rgb(245 158 11 / 8%);
}
.gsf-section--required .gsf-section-num { left: 16px; background: linear-gradient(135deg, var(--amber-700), var(--amber-500)); box-shadow: 0 0 0 4px var(--store-paper), 0 0 0 5px var(--amber-200); }
.gsf-section--required::before { left: 30px; }

.gsf-section--required .gsf-section-title::after {
    content: 'Required for this request';
    margin-left: 10px;
    font-size: 11px;
    font-weight: 700;
    letter-spacing: .06em;
    text-transform: uppercase;
    color: var(--amber-800);
    background: var(--amber-200);
    padding: 3px 8px;
    border-radius: 999px;
    vertical-align: middle;
}

/* Laser leatherette patch panel (conditional) — warm leather accent */
.gsf-patch-section {
    background: linear-gradient(180deg, var(--store-paper) 0%, var(--store-paper-deep) 100%);
    border: 1px solid var(--store-line);
    border-radius: 14px;
    margin: 6px -16px;
    padding: 22px 16px 22px 64px;
}
.gsf-patch-section::before { left: 30px; background: linear-gradient(180deg, var(--store-line), transparent); }

.gsf-patch-badge {
    left: 16px;
    background: linear-gradient(135deg, var(--garment-submit-form-orange), var(--garment-submit-form-orange-2));
    box-shadow: 0 0 0 4px var(--store-paper), 0 0 0 5px var(--store-line);
    font-size: 15px;
}
.gsf-patch-hint { margin-left: 0; }

/* ── Mini labels (inside garment / location rows) ───────────────────── */
.gsf-mini-label {
    font-size: 11px;
    font-weight: 700;
    color: var(--gray-500, var(--gray-500));
    text-transform: uppercase;
    letter-spacing: .06em;
}

/* ── Inline warnings & callouts ─────────────────────────────────────── */
.gsf-warn {
    color: var(--amber-800);
    background: var(--amber-100);
    border: 1px solid var(--amber-300);
    border-radius: 8px;
    padding: 7px 10px;
    font-weight: 500;
}

.gsf-approval-warn {
    margin: -6px 0 6px;
    padding: 14px 16px 14px 46px;
    position: relative;
    background: linear-gradient(180deg, var(--red-50) 0%, var(--red-100) 100%);
    border: 1px solid var(--orange-200);
    border-radius: 12px;
    font-size: 13px;
    color: var(--garment-submit-form-orange-4);
    line-height: 1.55;
}

.gsf-approval-warn::before {
    content: '!';
    position: absolute;
    left: 14px;
    top: 13px;
    width: 22px;
    height: 22px;
    border-radius: 50%;
    background: var(--garment-submit-form-orange-5);
    color: var(--color-on-brand);
    font-weight: 800;
    font-size: 13px;
    display: flex;
    align-items: center;
    justify-content: center;
}

/* ── Choice tiles (decoration methods + final checklist) ────────────── */
.gsf-check-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(196px, 1fr));
    gap: 8px;
}

.gsf-checklist-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 8px;
}

.gsf-check {
    display: flex;
    align-items: flex-start;
    gap: 10px;
    padding: 10px 12px;
    background: var(--color-surface);
    border: 1px solid var(--gray-200, var(--gray-200));
    border-radius: 10px;
    font-size: 13.5px;
    font-weight: 500;
    color: var(--gray-800, var(--gray-800));
    cursor: pointer;
    line-height: 1.4;
    user-select: none;
    transition: border-color .15s ease, background .15s ease, box-shadow .15s ease, color .15s ease;
}
.gsf-check:hover { border-color: var(--gray-300, var(--gray-300)); background: var(--gray-50, var(--gray-50)); }

.gsf-check input[type="checkbox"] {
    accent-color: var(--fx-accent);
    cursor: pointer;
    width: 16px;
    height: 16px;
    margin: 2px 0 0;
    flex: 0 0 auto;
}

.gsf-check:has(input:checked) {
    border-color: var(--fx-accent);
    background: var(--fx-tint);
    color: var(--fx-accent-dark);
    font-weight: 600;
    box-shadow: 0 0 0 3px var(--fx-ring);
}
.gsf-notext { margin-top: 10px; display: inline-flex; align-self: flex-start; font-size: 13px; }
.gsf-checklist-actions { margin-top: 10px; }

.gsf-checkall {
    background: var(--color-surface);
    border: 1px solid var(--gray-300, var(--gray-300));
    border-radius: 999px;
    padding: 6px 14px;
    font-size: 12.5px;
    font-weight: 600;
    color: var(--gray-600, var(--gray-600));
    cursor: pointer;
    font-family: inherit;
    transition: all .15s ease;
}

.gsf-checkall:hover {
    border-color: var(--state-success, var(--emerald-600));
    background: var(--state-success-bg, var(--brand-50));
}

/* ── Garment rows (Style → Color) ───────────────────────────────────── */
.gsf-garment-row,
.gsf-location-row {
    display: flex;
    align-items: flex-start;
    gap: 12px;
    padding: 12px 14px 12px 12px;
    background: var(--color-surface);
    border: 1px solid var(--gray-200, var(--gray-200));
    border-radius: 14px;
    margin-bottom: 10px;
    position: relative;
    box-shadow: var(--shadow-sm, 0 1px 2px rgb(15 23 42 / 4%));
    transition: border-color .15s ease, box-shadow .15s ease;
}

.gsf-garment-row:hover,
.gsf-location-row:hover { border-color: var(--gray-300, var(--gray-300)); box-shadow: var(--shadow-md, 0 4px 12px rgb(15 23 42 / 6%)); }

.gsf-garment-row:focus-within,
.gsf-location-row:focus-within { border-color: var(--fx-accent-light); }

.gsf-row-badge {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 24px;
    height: 24px;
    border-radius: 50%;
    background: var(--fx-tint);
    color: var(--fx-accent);
    font-size: 12px;
    font-weight: 800;
    flex: 0 0 auto;
    margin-top: 9px;
}
.gsf-location-row .gsf-row-badge { margin-top: 26px; }
.gsf-garment-style-field { flex: 1 1 40%; margin-bottom: 0; position: relative; }
.gsf-garment-color-field { flex: 1 1 45%; margin-bottom: 0; }

.gsf-swatch {
    width: 42px;
    height: 42px;
    border-radius: 10px;
    border: 1px solid var(--gray-200, var(--gray-200));
    object-fit: cover;
    flex: 0 0 auto;
    background: var(--color-surface);
    box-shadow: var(--shadow-sm, 0 1px 2px rgb(15 23 42 / 4%));
}

.gsf-swatch--empty {
    background: repeating-linear-gradient(45deg, var(--gray-100, var(--gray-100)) 0 6px, var(--color-surface) 6px 12px);
}

/* Style autocomplete dropdown */
.gsf-style-suggest {
    display: none;
    position: absolute;
    top: calc(100% + 6px);
    left: 0;
    right: 0;
    z-index: 50;
    background: var(--color-surface);
    border: 1px solid var(--gray-200, var(--gray-200));
    border-radius: 12px;
    box-shadow: var(--shadow-lg, 0 8px 24px -8px rgb(15 23 42 / 18%));
    max-height: 260px;
    overflow-y: auto;
    padding: 6px;
}

.gsf-style-opt {
    padding: 9px 12px;
    border-radius: 8px;
    font-size: 13px;
    color: var(--gray-800, var(--gray-800));
    cursor: pointer;
    transition: background .12s ease, color .12s ease;
}
.gsf-style-opt:hover { background: var(--fx-tint); color: var(--fx-accent); }

/* ── Location rows ──────────────────────────────────────────────────── */
.gsf-loc-grid {
    flex: 1;
    display: grid;
    grid-template-columns: 1.3fr .55fr .55fr 1.8fr;
    gap: 12px;
    min-width: 0;
}
.gsf-loc-grid .gsf-field { margin-bottom: 0; gap: 5px; }

/* Remove button on dynamic rows */
.gsf-row-remove {
    width: 26px;
    height: 26px;
    border-radius: 50%;
    border: none;
    background: var(--gray-100, var(--gray-100));
    color: var(--gray-500, var(--gray-500));
    cursor: pointer;
    font-size: 16px;
    line-height: 1;
    flex: 0 0 auto;
    margin-top: 8px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    transition: background .15s ease, color .15s ease;
}
.gsf-location-row .gsf-row-remove { margin-top: 26px; }
.gsf-row-remove:hover { background: var(--state-danger, var(--red-600)); color: var(--color-on-brand); }

/* Add-row button */
.gsf-add-btn {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    background: var(--color-surface);
    border: 1.5px dashed var(--gray-300, var(--gray-300));
    border-radius: 10px;
    padding: 9px 16px;
    font-size: 13px;
    font-weight: 600;
    color: var(--gray-600, var(--gray-600));
    cursor: pointer;
    font-family: inherit;
    transition: all .15s ease;
}

.gsf-add-btn:hover {
    border-color: var(--fx-accent);
    border-style: solid;
    color: var(--fx-accent);
    background: var(--fx-tint);
}

/* Carried-over artwork (Send to Steve) */
.gsf-file-badge {
    flex: 0 0 auto;
    font-size: 11px;
    font-weight: 700;
    letter-spacing: .04em;
    text-transform: uppercase;
    color: var(--color-floor-dark);
    background: var(--sky-100);
    border-radius: 999px;
    padding: 3px 9px;
}

.gsf-carried-status {
    margin-top: 10px;
    padding: 9px 12px;
    border-radius: 10px;
    font-size: 13px;
    background: var(--slate-100);
    color: var(--gray-700);
    border: 1px solid var(--slate-200);
}
.gsf-carried-status--ok    { background: var(--brand-50); color: var(--emerald-800); border-color: var(--emerald-200); }
.gsf-carried-status--error { background: var(--red-50); color: var(--red-800); border-color: var(--red-200); }

/* Rush toggle sits beside the Art Estimate select */
.gsf-rush-field { justify-content: flex-end; }
.gsf-rush-field .gsf-rush-toggle { align-self: flex-start; min-height: 42px; }

/* Colors-API failure for a garment row — visible warning + Retry, never a
   silent fallback to "custom" (which drops CATALOG_COLOR). */
.gsf-color-error {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    min-height: 42px;
    font-size: 12.5px;
    font-weight: 500;
    color: var(--red-800);
    background: var(--red-50);
    border: 1px solid var(--red-200);
    border-radius: 10px;
    padding: 6px 10px;
}

.gsf-color-retry {
    font-size: 12px;
    font-weight: 700;
    color: var(--color-on-brand);
    background: var(--state-success, var(--emerald-600));
    border: none;
    border-radius: 6px;
    padding: 5px 10px;
    cursor: pointer;
    font-family: inherit;
}
.gsf-color-retry:hover { background: var(--emerald-700); }
.gsf-color-retry:focus-visible { outline: 2px solid var(--emerald-700); outline-offset: 2px; }

/* ── Sticky progress bar (2026-09-04) ──────────────────────────────────
   The form is ~11,000px tall. This floats at the bottom of the viewport while
   the card is on screen: where you are, what is still required (click to jump
   to it), and a Submit that is never a long scroll away. Hidden while the real
   submit row is visible, and after a successful submit (garment-submit-form.js). */
.gsf-progress {
    position: fixed;
    left: 50%;
    bottom: 16px;
    transform: translateX(-50%);
    z-index: 60;
    display: flex;
    align-items: center;
    gap: 16px;
    width: min(920px, calc(100% - 32px));
    padding: 10px 12px 10px 18px;
    background: rgb(17 24 39 / 94%);
    color: var(--color-on-brand);
    border-radius: 14px;
    box-shadow: 0 16px 40px -12px rgb(0 0 0 / 55%);
    backdrop-filter: blur(8px);
}
.gsf-progress[hidden] { display: none; }
.gsf-progress__text { display: flex; flex-direction: column; gap: 2px; min-width: 0; flex: 1; font-size: 13px; }

.gsf-progress__text b {
    font-size: 11px; letter-spacing: .08em; text-transform: uppercase;
    color: rgb(255 255 255 / 70%); font-weight: 700;
}

.gsf-progress__left {
    background: none; border: 0; padding: 0; color: var(--color-on-brand); font: inherit; font-size: 13.5px;
    text-align: left; cursor: pointer; white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
}
.gsf-progress__left:hover { text-decoration: underline; }
.gsf-progress--ready .gsf-progress__left { color: var(--green-300); cursor: default; text-decoration: none; }

.gsf-progress__btn {
    flex: 0 0 auto; padding: 10px 20px; border: none; border-radius: 10px;
    background: var(--fx-grad); color: var(--color-on-brand); font: inherit; font-weight: 700; cursor: pointer;
    box-shadow: 0 8px 18px -8px rgb(0 0 0 / 60%);
    transition: filter .15s ease, box-shadow .15s ease;
}
.gsf-progress__btn:hover { filter: brightness(1.08); }
.gsf-progress--ready .gsf-progress__btn { box-shadow: 0 0 0 3px rgb(51 187 51 / 35%), 0 8px 18px -8px rgb(0 0 0 / 60%); }

/* ── Draft notice (2026-09-04) ──────────────────────────────────────── */
.gsf-draft-note {
    display: flex; align-items: center; justify-content: space-between; gap: 12px; flex-wrap: wrap;
    margin: 0 0 14px; padding: 12px 16px; border-radius: 12px;
    background: var(--store-paper); border: 1px solid var(--amber-200); color: var(--amber-900); font-size: 13.5px;
}

.gsf-draft-note__discard {
    background: var(--color-surface); border: 1px solid var(--amber-500); color: var(--amber-800); border-radius: 8px;
    padding: 6px 12px; font: inherit; font-size: 13px; font-weight: 600; cursor: pointer;
}
.gsf-draft-note__discard:hover { background: var(--amber-500); color: var(--color-on-brand); }

/* ── Responsive ─────────────────────────────────────────────────────── */
@media (width <= 760px) {
    .gsf-progress { bottom: 8px; padding: 8px 8px 8px 14px; gap: 10px; }
    .gsf-progress__text b { display: none; }
    .gsf-form-body { padding: 4px 18px 22px; }
    .gsf-row { grid-template-columns: 1fr; }
    .gsf-checklist-grid { grid-template-columns: 1fr; }
    .gsf-loc-grid { grid-template-columns: 1fr 1fr; }
    .gsf-banner { flex-direction: column; text-align: center; gap: 12px; padding: 22px 18px; }
    .gsf-banner-text p { max-width: none; }
    .gsf-garment-row { flex-wrap: wrap; }
    .gsf-section { padding-left: 42px; }
    .gsf-section--required, .gsf-patch-section { margin: 6px -6px; padding: 18px 10px 18px 52px; }
    .gsf-section--required .gsf-section-num, .gsf-patch-badge { left: 8px; }
    .gsf-section--required::before, .gsf-patch-section::before { left: 22px; }
    .gsf-section--required .gsf-section-title::after { display: none; }
}

@media (prefers-reduced-motion: reduce) {
    .gsf-rush-toggle--active,
    .gsf-rush-toggle--active .gsf-rush-icon,
    .gsf-success,
    .gsf-success-icon { animation: none; }
}

changes.after:
/* Compatibility URL for the lead and quote lazy loaders.
 * All garment form and contact picker rules belong to art-intake.css. */
@import url("/shared_components/css/art-intake.css?v=2026.09.12.1");

changes.before:
var GarmentSubmitForm = (function () {
    'use strict';

    var API_BASE = (window.APP_CONFIG && window.APP_CONFIG.API && window.APP_CONFIG.API.BASE_URL)
        || '';
    if (!API_BASE) console.error('[garment-submit-form] APP_CONFIG.API.BASE_URL missing — the proxy host is not configured');
    var SITE_ORIGIN = 'https://www.teamnwca.com';
    var STEVE_EMAIL = 'art@nwcustomapparel.com';
    var MAX_FILES = 4;
    var MAX_GARMENTS = 4;
    var MAX_LOCATIONS = 4;

    // ── Option lists ───────────────────────────────────────────────────────
    var ARTWORK_STATUSES = [
        'New artwork from scratch',
        'Mockup only',
        'Revision to existing proof',
        'Repeat from previous order',
        'Final approved / production ready'
    ];
    var APPROVAL_STATUSES = [
        'Not approved — Steve to create proof',
        'Customer reviewing proof',
        'Customer approved — ready for production',
        'Internal revision only',
        'Post-approval change order'
    ];
    var DECORATION_METHODS = [
        'Screen Print', 'DTG', 'Embroidery', 'Transfer',
        'Sticker', 'Banner', 'JDS Product', 'Laser Leatherette Patch', 'Not sure — Steve to advise'
    ];
    // ── Laser leatherette patch (laser-engraved patch applied to caps) ──────
    // When the AE picks this decoration method, a conditional "Patch Specs"
    // panel appears so Steve gets the patch-only details the print/embroidery
    // fields don't cover. Ships with NO new Caspio columns: the specs ride
    // inside the existing Artwork_Locations JSON (each patch placement carries
    // a `patch` object) + a readable block prepended to NOTES. Erik 2026-06-18.
    var PATCH_METHOD = 'Laser Leatherette Patch';
