    function resetForm() {
        referenceFiles = [];
        prefilledUploads = [];
        selectedContact = null;
        selectedDesign = null;
        isRush = false;
        submitted = false;
        dirty = false;
        draftPrelim = '';
        clearDraft();
        garmentRows = [newGarmentRow()];
        artworkLocations = [newLocation()];
        renderForm();
