    function initSalesRep() {
        var repInput = document.getElementById('gsf-sales-rep');
        if (!repInput) return;
        if (typeof StaffAuthHelper !== 'undefined' && StaffAuthHelper.isLoggedIn()) {
            var name = StaffAuthHelper.getLoggedInStaffName();
