        }
        try {
            emailjs.init(((typeof window !== 'undefined' && window.APP_CONFIG && window.APP_CONFIG.EMAIL && window.APP_CONFIG.EMAIL.PUBLIC_KEY) || ''));
            var detailLink = SITE_ORIGIN + '/art-request/' + (designId || '');
            emailjs.send(((typeof window !== 'undefined' && window.APP_CONFIG && window.APP_CONFIG.EMAIL && window.APP_CONFIG.EMAIL.SERVICE_ID) || ''), 'template_art_note_added', {
                to_email: STEVE_EMAIL,
                to_name: 'Steve',
                design_id: designId || 'NEW',
                company_name: companyName,
                note_text: 'New garment art request from ' + aeName + ' for ' + companyName,
                note_type: 'New Garment Submission',
                header_emoji: '\u{1F455}',
                header_title: 'New Garment Art Request',
                detail_link: detailLink,
                from_name: aeName
            }).catch(function (err) {
                console.error('[GarmentSubmitForm] EmailJS send to Steve failed for design', designId, err);
                notifySteveFailed();
            });

            if (aeEmail && aeEmail !== STEVE_EMAIL) {
                emailjs.send(((typeof window !== 'undefined' && window.APP_CONFIG && window.APP_CONFIG.EMAIL && window.APP_CONFIG.EMAIL.SERVICE_ID) || ''), 'template_art_note_added', {
                    to_email: aeEmail,
                    to_name: aeName,
                    design_id: designId || 'NEW',
                    company_name: companyName,
                    note_text: 'Your garment art request for ' + companyName + ' was submitted to Steve.',
                    note_type: 'Submission Confirmation',
                    header_emoji: '✅',
                    header_title: 'Request Submitted',
                    detail_link: detailLink + '?view=ae',
                    from_name: 'NWCA Art Department'
                }).catch(function () {});
            }

            if (salesRepEmail && salesRepEmail !== STEVE_EMAIL && salesRepEmail !== aeEmail) {
                emailjs.send(((typeof window !== 'undefined' && window.APP_CONFIG && window.APP_CONFIG.EMAIL && window.APP_CONFIG.EMAIL.SERVICE_ID) || ''), 'template_art_note_added', {
                    to_email: salesRepEmail,
                    to_name: salesRepName || 'Sales Rep',
                    design_id: designId || 'NEW',
                    company_name: companyName,
                    note_text: 'A garment art request for ' + companyName + ' was submitted to Steve on your behalf by ' + aeName + '.',
                    note_type: 'Submission FYI (Sales Rep)',
                    header_emoji: '\u{1F4E8}',
                    header_title: 'Art Request — FYI',
                    detail_link: detailLink + '?view=ae',
                    from_name: 'NWCA Art Department'
                }).catch(function () {});
            }
        } catch (e) {
            console.error('[GarmentSubmitForm] EmailJS setup failed — Steve was NOT notified for design', designId, e);
            notifySteveFailed();
        }
    }

    // ── Success ────────────────────────────────────────────────────────────
    function showSuccess(designId, companyName) {
        submitted = true;          // the leave-page guard stands down
        dirty = false;
        clearDraft();              // the request is in Caspio now — no draft to restore
        setProgressVisible(false);
        var body = document.getElementById('gsf-form-body');
        body.innerHTML = '<div class="gsf-success">'
            + '<div class="gsf-success-icon">✅</div>'
            + '<h3>Art Request Submitted!' + (designId ? ' <span class="gsf-success-id">Design #' + escapeHtml(String(designId)) + '</span>' : '') + '</h3>'
            + '<p>Your garment art request for <strong>' + escapeHtml(companyName) + '</strong> has been sent to Steve with all the details. He will create the mockup and notify you when it\'s ready.</p>'
            + (designId ? '<a href="/art-request/' + designId + '?view=ae" class="gsf-success-link">View Request →</a>' : '')
            + '<button type="button" class="gsf-success-another" id="gsf-another-btn">Submit Another</button>'
            + '</div>';
        var anotherBtn = document.getElementById('gsf-another-btn');
        if (anotherBtn) anotherBtn.addEventListener('click', resetForm);
    }

    function resetForm() {
        referenceFiles = [];
        prefilledUploads = [];
        selectedContact = null;
        selectedDesign = null;
        isRush = false;
        submitted = false;
        dirty = false;
        draftPrelim = '';
        clearDraft();
        garmentRows = [newGarmentRow()];
        artworkLocations = [newLocation()];
        renderForm();
    }

    // ── 2026-09-04 review additions ────────────────────────────────────────

    /* (a) Programmatic labels. The visual labels never carried `for`, so a screen
       reader announced 35 of the 58 controls as "edit text". Pair each field's
       label with the first control that has an id. Runs after every render,
       including the location rows. */
    function wireLabels() {
        var root = document.getElementById(containerId);
        if (!root) return;
        root.querySelectorAll('.gsf-field').forEach(function (field) {
            var label = field.querySelector('.gsf-label, .gsf-mini-label');
            if (!label || label.htmlFor) return;
            var ctrl = field.querySelector('input[id]:not([type="hidden"]):not([type="file"]), select[id], textarea[id]');
            if (ctrl) label.htmlFor = ctrl.id;
        });
    }

    /* (b) Art fee options from Caspio Service_Codes — the GRT-* rows Steve
       actually bills. The typed list this replaced offered GRT-25/100/150, parts
       that do not exist. Option value = SellPrice, which is what Prelim_Charges
       stores. On failure the select says so; it is optional, so the request
       still goes through and Steve sets the fee. */
    var draftPrelim = '';
    function loadArtFeeOptions() {
        var sel = document.getElementById('gsf-prelim');
        var warn = document.getElementById('gsf-prelim-warning');
        if (!sel) return;
        fetch(API_BASE + '/api/service-codes')
            .then(function (r) { if (!r.ok) throw new Error('HTTP ' + r.status); return r.json(); })
            .then(function (d) {
                var rows = (d && (d.data || d.Result)) || (Array.isArray(d) ? d : []);
                var fees = rows.filter(function (r) {
                    return /^GRT-/i.test(String(r.ServiceCode || '')) && r.IsActive !== false && r.SellPrice != null;
                }).sort(function (a, b) { return Number(a.SellPrice) - Number(b.SellPrice); });
                if (!fees.length) throw new Error('no GRT-* rows in Service_Codes');
                var html = '<option value="">- select -</option>';
                fees.forEach(function (f) {
                    var per = /hour/i.test(String(f.PerUnit || '')) ? '/hr' : '';
                    html += '<option value="' + escapeAttr(String(f.SellPrice)) + '">'
                        + escapeHtml(f.ServiceCode + ' · ' + (f.DisplayName || '') + ' — $' + Number(f.SellPrice).toFixed(0) + per)
                        + '</option>';
                });
                sel.innerHTML = html;
                sel.disabled = false;
                if (draftPrelim) { sel.value = draftPrelim; draftPrelim = ''; }
                if (warn) { warn.textContent = ''; warn.style.display = 'none'; }
            })
            .catch(function (err) {
                console.error('[GarmentSubmitForm] art fee list failed to load:', err);
                sel.innerHTML = '<option value="">- art fees unavailable -</option>';
                sel.disabled = true;
                if (warn) {
                    warn.textContent = 'Could not load the art fee list from Caspio (' + err.message + '). Leave this blank — Steve will set the fee — or refresh to retry.';
                    warn.style.display = 'block';
                }
            });
    }

    /* (c) Sticky progress bar. The form is ~11,000px tall; this tells the rep
       where they are and what is still required, and carries a Submit button
       so the real one is never a long scroll away. Hidden while the real submit
       row is on screen, and after a successful submit. */
    var SECTION_TOTAL = 11;
    var progressVisibleOk = false;   // form card in view
    var submitRowInView = false;
    function buildProgressHtml() {
        return '<div class="gsf-progress" id="gsf-progress" hidden>'
            + '<div class="gsf-progress__text">'
            + '<b id="gsf-progress-where">Section 1 of ' + SECTION_TOTAL + '</b>'
            + '<button type="button" class="gsf-progress__left" id="gsf-progress-left" title="Jump to the next required field"></button>'
            + '</div>'
            + '<button type="button" class="gsf-progress__btn" id="gsf-progress-submit">Submit Art Request</button>'
            + '</div>';
    }
    function setProgressVisible(on) {
        var bar = document.getElementById('gsf-progress');
        if (bar) bar.hidden = !on;
    }
    function syncProgressVisibility() {
        setProgressVisible(progressVisibleOk && !submitRowInView && !submitted);
    }
    function initProgress() {
        var card = document.querySelector('#' + containerId + ' .gsf-form-card');
        var submitRow = document.querySelector('#' + containerId + ' .gsf-submit-row');
        var bar = document.getElementById('gsf-progress');
        if (!card || !bar) return;
        progressVisibleOk = false; submitRowInView = false;
        if (typeof IntersectionObserver === 'function') {
            new IntersectionObserver(function (entries) {
                entries.forEach(function (en) { progressVisibleOk = en.isIntersecting; });
                syncProgressVisibility();
            }, { rootMargin: '-120px 0px 0px 0px' }).observe(card);
            if (submitRow) {
                new IntersectionObserver(function (entries) {
                    entries.forEach(function (en) { submitRowInView = en.isIntersecting; });
                    syncProgressVisibility();
                }).observe(submitRow);
            }
        } else {
            progressVisibleOk = true;
            syncProgressVisibility();
        }
        var go = document.getElementById('gsf-progress-submit');
        if (go) go.addEventListener('click', handleSubmit);
        var left = document.getElementById('gsf-progress-left');
        if (left) left.addEventListener('click', function () {
            var m = countMissing();
            if (!m.length) return;
            var el = document.getElementById(m[0].id);
            if (!el) return;
            el.scrollIntoView({ behavior: 'smooth', block: 'center' });
            if (typeof el.focus === 'function') setTimeout(function () { el.focus({ preventScroll: true }); }, 400);
        });
        // "Section N of 11" — the numbered section nearest the top of the viewport.
        var sections = [].slice.call(document.querySelectorAll('#' + containerId + ' .gsf-section')).filter(function (s) { return s.querySelector('.gsf-section-num'); });
        var ticking = false;
        function whereAmI() {
            ticking = false;
            var where = document.getElementById('gsf-progress-where');
            if (!where) return;
            var line = 140, n = 1;
            sections.forEach(function (s, i) { if (s.getBoundingClientRect().top <= line) n = i + 1; });
            where.textContent = 'Section ' + n + ' of ' + sections.length;
        }
        window.addEventListener('scroll', function () {
            if (!ticking) { ticking = true; requestAnimationFrame(whereAmI); }
        }, { passive: true });
        whereAmI();
    }
    /* Same rules as validate(), without touching the error states. */
    function countMissing() {
        var missing = [];
        function need(id, ok, label) { if (!ok) missing.push({ id: id, label: label }); }
        need('gsf-company', !!getVal('gsf-company'), 'Company');
        need('gsf-contact-name', !!getVal('gsf-contact-name'), 'Contact name');
        need('gsf-due-date', !!getVal('gsf-due-date'), 'Due date');
        need('gsf-design-num', !!getVal('gsf-design-num'), 'Design #');
        need('gsf-order-num', !!getVal('gsf-order-num'), 'Order #');
        need('gsf-artwork-status', !!getVal('gsf-artwork-status'), 'Artwork status');
        need('gsf-approval-status', !!getVal('gsf-approval-status'), 'Approval status');
        need('gsf-decoration-error', document.querySelectorAll('.gsf-decoration:checked').length > 0, 'Decoration method');
        if (isPatchSelected()) {
            need('gsf-patch-material', !!getVal('gsf-patch-material'), 'Leatherette color');
            if (getVal('gsf-patch-material') === PATCH_MATERIAL_OTHER) need('gsf-patch-material-other', !!getVal('gsf-patch-material-other'), 'Patch material');
            need('gsf-patch-shape', !!getVal('gsf-patch-shape'), 'Patch shape');
            need('gsf-patch-width', !!getVal('gsf-patch-width'), 'Patch width');
            need('gsf-patch-attach', !!getVal('gsf-patch-attach'), 'Patch attachment');
        }
        syncLocationsFromDom();
        need('gsf-loc-place-0', artworkLocations.some(function (l) { return l.placement && l.width; }), 'Artwork placement + width');
        need('gsf-color-mode', !!getVal('gsf-color-mode'), 'Color direction');
        var noText = document.getElementById('gsf-no-text');
        need('gsf-exact-text', !!getVal('gsf-exact-text') || !!(noText && noText.checked), 'Exact text');
        if (isRepeatOrRevision()) {
            need('gsf-prev-order', !!getVal('gsf-prev-order'), 'Previous order #');
            need('gsf-prev-design', !!getVal('gsf-prev-design'), 'Previous design #');
            if (currentArtworkStatus() === 'Revision to existing proof') need('gsf-change', !!getVal('gsf-change'), 'What should change');
        }
        var fileType = getVal('gsf-file-type');
        var hasSource = referenceFiles.length > 0 || prefilledUploads.length > 0 || !!getVal('gsf-prev-design') || fileType === FILE_TYPES[4] || fileType === FILE_TYPES[3];
        need('gsf-file-type', !!fileType && hasSource, 'File type / artwork');
        var total = document.querySelectorAll('.gsf-checklist').length;
        var checked = document.querySelectorAll('.gsf-checklist:checked').length;
        need('gsf-check-all', total > 0 && checked === total, 'Final checklist');
        return missing;
    }
    function updateProgress() {
        var left = document.getElementById('gsf-progress-left');
        var bar = document.getElementById('gsf-progress');
        if (!left || !bar) return;
        var m = countMissing();
        if (!m.length) {
            left.textContent = 'Everything required is filled in';
            bar.classList.add('gsf-progress--ready');
        } else {
            left.textContent = m.length + ' required left · next: ' + m[0].label;
            bar.classList.remove('gsf-progress--ready');
        }
    }

    /* (d) Leave-page guard + per-rep draft. Any edit marks the form dirty; leaving
       with unsent edits asks first. Every edit also saves a draft (debounced) that
       init() restores on the next visit — fields, checkboxes, garment rows,
       locations and the rush flag. Files cannot be drafted; the notice says so. */
    var dirty = false;
    var submitted = false;
    var draftTimer = null;
    var DRAFT_TTL_MS = 7 * 24 * 60 * 60 * 1000;
    function draftOwner() {
        try {
            if (typeof StaffAuthHelper !== 'undefined' && StaffAuthHelper.getLoggedInStaffEmail) {
                var e = StaffAuthHelper.getLoggedInStaffEmail();
                if (e) return String(e).toLowerCase();
            }
        } catch (x) { /* fall through */ }
        try { return (localStorage.getItem('userEmail') || 'anon').toLowerCase(); } catch (x) { return 'anon'; }
    }
    function draftKey() { return 'nwca-gsf-draft:' + draftOwner(); }
    function initDirtyTracking() {
        var body = document.getElementById('gsf-form-body');
        if (!body) return;
        ['input', 'change'].forEach(function (ev) {
            body.addEventListener(ev, function () {
                dirty = true;
                clearTimeout(draftTimer);
                draftTimer = setTimeout(saveDraft, 600);
                updateProgress();
            });
        });
        if (!window.__gsfUnloadGuard) {
            window.__gsfUnloadGuard = true;
            window.addEventListener('beforeunload', function (e) {
                if (dirty && !submitted) { e.preventDefault(); e.returnValue = ''; }
            });
        }
    }
    function checkboxKey(cb) {
        if (cb.id) return cb.id;
        if (cb.dataset && cb.dataset.key) return 'chk:' + cb.dataset.key;
        return 'deco:' + cb.value;
    }
    function collectDraft() {
        var fields = {}, checks = {};
        document.querySelectorAll('#gsf-form-body input[id], #gsf-form-body select[id], #gsf-form-body textarea[id]').forEach(function (el) {
            if (el.type === 'file' || el.type === 'checkbox') return;
            if (/^gsf-(style|color|loc)-/.test(el.id)) return;   // rows are stored structurally
            fields[el.id] = el.value;
        });
        document.querySelectorAll('#gsf-form-body input[type="checkbox"]').forEach(function (cb) { checks[checkboxKey(cb)] = cb.checked; });
        syncGarmentColorsFromDom();
        syncLocationsFromDom();
        return {
            v: 1, savedAt: Date.now(), fields: fields, checks: checks, isRush: isRush,
            garments: garmentRows.map(function (r) { return { style: r.style, colorName: r.colorName, catalogColor: r.catalogColor, swatch: r.swatch, image: r.image, custom: !!r.custom }; }),
            locations: artworkLocations.map(function (l) { return { placement: l.placement, width: l.width, height: l.height, notes: l.notes }; })
        };
    }
    function saveDraft() {
        if (submitted) return;
        try {
            var d = collectDraft();
            var meaningful = Object.keys(d.fields).some(function (k) {
                return d.fields[k] && k !== 'gsf-sales-rep' && k !== 'gsf-due-date' && k !== 'gsf-customer-id';
            }) || d.garments.some(function (g) { return g.style; });
            if (!meaningful) { localStorage.removeItem(draftKey()); return; }
            localStorage.setItem(draftKey(), JSON.stringify(d));
        } catch (e) { /* quota / private mode — drafts are best-effort */ }
    }
    function clearDraft() { try { localStorage.removeItem(draftKey()); } catch (e) { /* ignore */ } }
    function readDraft() {
        try {
            var raw = localStorage.getItem(draftKey());
            if (!raw) return null;
            var d = JSON.parse(raw);
            if (!d || d.v !== 1 || (Date.now() - d.savedAt) > DRAFT_TTL_MS) return null;
            return d;
        } catch (e) { return null; }
    }
    function restoreDraft(d) {
        Object.keys(d.fields || {}).forEach(function (id) {
            var el = document.getElementById(id);
            if (el && d.fields[id]) el.value = d.fields[id];
        });
        draftPrelim = (d.fields && d.fields['gsf-prelim']) || '';
        document.querySelectorAll('#gsf-form-body input[type="checkbox"]').forEach(function (cb) {
            var key = checkboxKey(cb);
            if (d.checks && key in d.checks) cb.checked = !!d.checks[key];
        });
        if (Array.isArray(d.garments) && d.garments.length) {
            garmentRows = d.garments.map(function (g) {
                var r = newGarmentRow();
                r.style = g.style || ''; r.colorName = g.colorName || ''; r.catalogColor = g.catalogColor || '';
                r.swatch = g.swatch || ''; r.image = g.image || ''; r.custom = !!g.custom;
                return r;
            });
            renderGarmentRows();
            garmentRows.forEach(function (r, i) { if (r.style && !r.custom) loadColorsForRow(i, r.style); });
        }
        if (Array.isArray(d.locations) && d.locations.length) {
            artworkLocations = d.locations.map(function (l) { return { placement: l.placement || '', width: l.width || '', height: l.height || '', notes: l.notes || '' }; });
            renderLocations();
        }
        if (d.isRush) {
            isRush = true;
            var rb = document.getElementById('gsf-rush-toggle');
            if (rb) { rb.classList.add('gsf-rush-toggle--active'); rb.setAttribute('aria-pressed', 'true'); }
        }
        var noText = document.getElementById('gsf-no-text'), ta = document.getElementById('gsf-exact-text');
        if (noText && ta && noText.checked) ta.disabled = true;
        try { applyArtworkStatusAdaptive(); applyApprovalAdaptive(); applyPatchVisibility(); applyPatchMaterialOther(); } catch (e) { /* non-fatal */ }
        dirty = true;
        updateProgress();
    }
    function initDraft() {
        var d = readDraft();
        if (!d) return;
        restoreDraft(d);
        var card = document.querySelector('#' + containerId + ' .gsf-form-card');
        if (!card || document.getElementById('gsf-draft-note')) return;
        var when = new Date(d.savedAt);
        var note = document.createElement('div');
        note.className = 'gsf-draft-note';
        note.id = 'gsf-draft-note';
        note.innerHTML = '<span>Restored your unsent request from <b>' + escapeHtml(when.toLocaleString([], { month: 'short', day: 'numeric', hour: 'numeric', minute: '2-digit' })) + '</b>. Files need re-attaching.</span>'
            + '<button type="button" class="gsf-draft-note__discard" id="gsf-draft-discard">Discard draft</button>';
        card.parentNode.insertBefore(note, card);
        document.getElementById('gsf-draft-discard').addEventListener('click', function () {
            clearDraft();
            resetForm();
        });
    }

    // ── Helpers ────────────────────────────────────────────────────────────
    function escapeHtml(str) {
        if (str === null || str === undefined) return '';
        var div = document.createElement('div');
        div.textContent = String(str);
        return div.innerHTML;
    }
    function escapeAttr(str) {
        return escapeHtml(str).replace(/"/g, '&quot;');
    }
    function formatFileSize(bytes) {
        if (bytes < 1024) return bytes + ' B';
        if (bytes < 1024 * 1024) return Math.round(bytes / 1024) + ' KB';
        return (bytes / (1024 * 1024)).toFixed(1) + ' MB';
    }
    // Returns '' when the staff session is missing. It used to fall back to
    // 'ae@nwcustomapparel.com' — an inbox nobody owns — so the request saved
    // with a bogus User_Email and the AE's own confirmation email went nowhere.
    // Steve still got his (his address is hardcoded), which is why it went
    // unnoticed for 14 requests. Never invent a submitter; block instead.
    function getSubmitterEmail() {
        if (typeof StaffAuthHelper !== 'undefined') {
            var email = StaffAuthHelper.getLoggedInStaffEmail();
            if (email) return email;
        }
        if (window.APP_CONFIG && window.APP_CONFIG.USER && window.APP_CONFIG.USER.email) return window.APP_CONFIG.USER.email;
        return localStorage.getItem('userEmail') || '';
    }
    function getSubmitterName() {
        if (typeof StaffAuthHelper !== 'undefined') {
            var name = StaffAuthHelper.getLoggedInStaffName();
            if (name) return name;
        }
        if (window.APP_CONFIG && window.APP_CONFIG.USER && window.APP_CONFIG.USER.name) return window.APP_CONFIG.USER.name;
        var email = getSubmitterEmail();
        if (!email) return '';
        var atIdx = email.indexOf('@');
        var local = atIdx > 0 ? email.substring(0, atIdx) : email;
        return local.charAt(0).toUpperCase() + local.slice(1);
    }
    function showToast(message, type) {
        type = type || 'info';
        document.querySelectorAll('.gsf-toast').forEach(function (t) { t.remove(); });
        var toast = document.createElement('div');
        toast.className = 'gsf-toast gsf-toast--' + type;
        toast.textContent = message;
        document.body.appendChild(toast);
        requestAnimationFrame(function () { toast.classList.add('show'); });
        setTimeout(function () { toast.classList.remove('show'); setTimeout(function () { toast.remove(); }, 300); }, 3500);
    }

    return {
        init: init,
        // Exposed for unit testing the submitter-identity guard. An unidentified
        // staffer MUST resolve to '' so handleSubmit blocks — never to a stand-in
        // inbox, which is what silently swallowed 14 AEs' confirmation emails.
        _getSubmitterIdentityForTest: function () {
            return { email: getSubmitterEmail(), name: getSubmitterName() };
        },
        // Exposed for unit testing of the payload contract.
        _buildPayloadForTest: function (deps) {
            garmentRows = deps.garmentRows || garmentRows;
            artworkLocations = deps.artworkLocations || artworkLocations;
            isRush = !!deps.isRush;
            return buildPayload(deps.companyName, deps.aeName, deps.aeEmail, deps.salesRep, deps.uploaded || []);
        }
    };

})();

changes.before:
/* Art intake family: common form controls, uploads and customer lookup.
 * Four existing request types keep their business hooks and department accents. */
@layer components.patterns {
    :where([data-ui="unified"][data-art-intake]) {
        --mockup-submit-form-teal-dark-2: var(--emerald-800);
        --sticker-banner-submit-form-green-tint: var(--color-steve-tint);
        --sticker-banner-submit-form-teal-dark-2: var(--emerald-800);
        --garment-submit-form-green-tint: var(--color-steve-tint);
        --garment-submit-form-teal-dark-2: var(--emerald-800);
        --garment-submit-form-orange: var(--amber-900);
        --garment-submit-form-orange-2: var(--amber-800);
        --garment-submit-form-orange-4: var(--amber-800);
        --garment-submit-form-orange-5: var(--amber-700);
        --jds-submit-form-green-tint: var(--color-steve-tint);
        --jds-submit-form-teal-dark-2: var(--emerald-800);
    }

    :where([data-ui="unified"][data-art-intake]) .msf-container {
        --fx-accent: var(--color-ruth);
        --fx-accent-dark: var(--color-ruth-dark);
        --fx-accent-light: var(--color-ruth-light);
        --fx-tint: var(--color-ruth-tint);
        --fx-tint-2: var(--color-ruth-tint);
        --fx-ring: rgb(107 70 193 / 16%);
        --fx-grad: var(--fx-accent);

        max-width: 900px;
        margin: 0 auto;
        font-family: var(--ui-font);
        color: var(--gray-800, var(--gray-800));

        --art-theme: var(--fx-accent);
        --art-theme-dark: var(--fx-accent-dark);
        --art-theme-light: var(--fx-accent-light);
        --art-theme-bg: var(--fx-tint);
        --art-theme-bg-hover: var(--fx-tint);
        --art-theme-bg-selected: var(--fx-tint-2);
        --art-theme-rgba-15: var(--fx-ring);
        --art-theme-rgba-10: rgb(107 70 193 / 10%);
    }

    :where([data-ui="unified"][data-art-intake]) .msf-form-card,
    :where([data-ui="unified"][data-art-intake]) .sbf-form-card,
    :where([data-ui="unified"][data-art-intake]) .gsf-form-card,
    :where([data-ui="unified"][data-art-intake]) .jds-form-card {
        background: var(--color-surface);
        border: 1px solid var(--gray-200, var(--gray-200));
        border-radius: 18px;
        box-shadow: none;
    }

    :where([data-ui="unified"][data-art-intake]) .msf-form-header,
    :where([data-ui="unified"][data-art-intake]) .sbf-form-header,
    :where([data-ui="unified"][data-art-intake]) .jds-form-header {
        display: flex;
        align-items: center;
        gap: 10px;
        padding: 14px 28px;
        background: var(--gray-50, var(--gray-50));
        border-bottom: 1px solid var(--gray-200, var(--gray-200));
        border-radius: 18px 18px 0 0;
        font-size: 12px;
        font-weight: 700;
        letter-spacing: 0.08em;
        text-transform: uppercase;
        color: var(--gray-600, var(--gray-600));
    }

    :where([data-ui="unified"][data-art-intake]) .msf-form-header::before,
    :where([data-ui="unified"][data-art-intake]) .sbf-form-header::before,
    :where([data-ui="unified"][data-art-intake]) .jds-form-header::before {
        content: "";
        width: 8px;
        height: 8px;
        border-radius: 50%;
        background: var(--fx-accent);
        box-shadow: none;
    }

    :where([data-ui="unified"][data-art-intake]) .msf-form-body,
    :where([data-ui="unified"][data-art-intake]) .sbf-form-body,
    :where([data-ui="unified"][data-art-intake]) .jds-form-body {
        padding: 26px 28px 28px;
    }

    :where([data-ui="unified"][data-art-intake]) .msf-row,
    :where([data-ui="unified"][data-art-intake]) .sbf-row,
    :where([data-ui="unified"][data-art-intake]) .gsf-row,
    :where([data-ui="unified"][data-art-intake]) .jds-row {
        display: grid;
        grid-template-columns: 1fr 1fr;
        gap: 0 20px;
    }

    :where([data-ui="unified"][data-art-intake]) .msf-field,
    :where([data-ui="unified"][data-art-intake]) .sbf-field,
    :where([data-ui="unified"][data-art-intake]) .gsf-field,
    :where([data-ui="unified"][data-art-intake]) .jds-field {
        display: flex;
        flex-direction: column;
        gap: 6px;
        margin-bottom: 18px;
        min-width: 0;
    }

    :where([data-ui="unified"][data-art-intake]) .msf-field-label,
    :where([data-ui="unified"][data-art-intake]) .sbf-field-label,
    :where([data-ui="unified"][data-art-intake]) .jds-field-label {
        display: flex;
        align-items: center;
        gap: 4px;
        font-size: 13px;
        font-weight: 600;
        color: var(--gray-700, var(--gray-700));
        letter-spacing: -0.005em;
        line-height: 1.3;
    }

    :where([data-ui="unified"][data-art-intake]) .msf-required,
    :where([data-ui="unified"][data-art-intake]) .sbf-required,
    :where([data-ui="unified"][data-art-intake]) .jds-required {
        color: var(--fx-accent);
        font-weight: 700;
    }

    :where([data-ui="unified"][data-art-intake]) .msf-field-hint,
    :where([data-ui="unified"][data-art-intake]) .sbf-field-hint,
    :where([data-ui="unified"][data-art-intake]) .jds-field-hint {
        font-size: 12px;
        color: var(--ui-muted);
        line-height: 1.45;
        margin-top: 2px;
    }

    :where([data-ui="unified"][data-art-intake]) .msf-input,
    :where([data-ui="unified"][data-art-intake]) .msf-select,
    :where([data-ui="unified"][data-art-intake]) .msf-textarea,
    :where([data-ui="unified"][data-art-intake]) .sbf-input,
    :where([data-ui="unified"][data-art-intake]) .sbf-select,
    :where([data-ui="unified"][data-art-intake]) .sbf-textarea,
    :where([data-ui="unified"][data-art-intake]) .gsf-input,
    :where([data-ui="unified"][data-art-intake]) .gsf-select,
    :where([data-ui="unified"][data-art-intake]) .gsf-textarea,
    :where([data-ui="unified"][data-art-intake]) .jds-input,
    :where([data-ui="unified"][data-art-intake]) .jds-select,
    :where([data-ui="unified"][data-art-intake]) .jds-textarea {
        width: 100%;
        box-sizing: border-box;
        min-height: 42px;
        padding: 10px 13px;
        border: 1px solid var(--gray-300, var(--gray-300));
        border-radius: 10px;
        font-size: 14px;
        font-family: var(--ui-font);
        color: var(--gray-900, var(--gray-900));
        background-color: var(--color-on-brand);
        box-shadow: none;
        transition:
            border-color 0.15s ease,
            box-shadow 0.15s ease,
            background-color 0.15s ease;
    }

    :where([data-ui="unified"][data-art-intake]) .msf-input:hover,
    :where([data-ui="unified"][data-art-intake]) .msf-select:hover,
    :where([data-ui="unified"][data-art-intake]) .msf-textarea:hover,
    :where([data-ui="unified"][data-art-intake]) .sbf-input:hover,
    :where([data-ui="unified"][data-art-intake]) .sbf-select:hover,
    :where([data-ui="unified"][data-art-intake]) .sbf-textarea:hover,
    :where([data-ui="unified"][data-art-intake]) .gsf-input:hover,
    :where([data-ui="unified"][data-art-intake]) .gsf-select:hover,
    :where([data-ui="unified"][data-art-intake]) .gsf-textarea:hover,
    :where([data-ui="unified"][data-art-intake]) .jds-input:hover,
    :where([data-ui="unified"][data-art-intake]) .jds-select:hover,
    :where([data-ui="unified"][data-art-intake]) .jds-textarea:hover {
        border-color: var(--gray-400, var(--gray-400));
    }

    :where([data-ui="unified"][data-art-intake]) .msf-input:focus,
    :where([data-ui="unified"][data-art-intake]) .msf-select:focus,
    :where([data-ui="unified"][data-art-intake]) .msf-textarea:focus,
    :where([data-ui="unified"][data-art-intake]) .sbf-input:focus,
    :where([data-ui="unified"][data-art-intake]) .sbf-select:focus,
    :where([data-ui="unified"][data-art-intake]) .sbf-textarea:focus,
    :where([data-ui="unified"][data-art-intake]) .gsf-input:focus,
    :where([data-ui="unified"][data-art-intake]) .gsf-select:focus,
    :where([data-ui="unified"][data-art-intake]) .gsf-textarea:focus,
    :where([data-ui="unified"][data-art-intake]) .jds-input:focus,
    :where([data-ui="unified"][data-art-intake]) .jds-select:focus,
    :where([data-ui="unified"][data-art-intake]) .jds-textarea:focus {
        outline: none;
        border-color: var(--fx-accent);
        box-shadow: none;
    }

    :where([data-ui="unified"][data-art-intake]) .msf-input::placeholder,
    :where([data-ui="unified"][data-art-intake]) .msf-textarea::placeholder,
    :where([data-ui="unified"][data-art-intake]) .sbf-input::placeholder,
    :where([data-ui="unified"][data-art-intake]) .sbf-textarea::placeholder,
    :where([data-ui="unified"][data-art-intake]) .gsf-input::placeholder,
